def minCostTravel(matrix: List[List[int]]) -> int:

    n = len(matrix)
    if n == 1:
        return min(matrix[0])

    dp = [[0, 0, 0] for _ in range(n)]
    dp[0] = matrix[0]

    for i in range(1, n):
        dp[i][0] = matrix[i][0] + min(dp[i-1][1], dp[i-1][2])
        dp[i][1] = matrix[i][1] + min(dp[i-1][0], dp[i-1][2])
        dp[i][2] = matrix[i][2] + min(dp[i-1][0], dp[i-1][1])

    return min(dp[n-1])

