def selection_sort(numbers):

    # Loop through all the elements in the list (except for the last one)
    for i in range(len(numbers) - 1):
        # Find the index of the smallest number from the remaining elements of the list
        min_index = i
        for j in range(i + 1, len(numbers)):
            if numbers[j] < numbers[min_index]:
                min_index = j

        # Swap the smallest number found with the current number at the current index of the loop
        numbers[i], numbers[min_index] = numbers[min_index], numbers[i]

    return numbers

