def is_anagram(s1, s2):

    # If lengths are not the same, they cannot be anagrams
    if len(s1) != len(s2):
        return False

    # Sort both strings
    s1 = sorted(s1)
    s2 = sorted(s2)

    # Compare sorted strings
    for i in range(0, len(s1)):
        if s1[i] != s2[i]:
            return False

    return True

def assess_password(password):

    if len(password) < 8:
        return False

    has_letter = False
    has_number = False
    has_symbol = False

    for char in password:
        if char.isalpha():
            has_letter = True
        elif char.isdigit():
            has_number = True
        else:
            has_symbol = True

    if has_letter and has_number and has_symbol:
        return True
    else:
        return False

